/* @lc app=leetcode id=2492 lang=kotlin */
class Solution { fun minScore(n: Int, roads: Array<IntArray>): Int = roads.fold(IntArray(n + 1) { 1000001 } to IntArray(n + 1) { it }) { (mW, p), r -> (generateSequence(r[0]) { p[it].takeIf { it != p[it] } }.last()).let { rU -> (generateSequence(r[1]) { p[it].takeIf { it != p[it] } }.last()).let { rV -> if (rU != rV) p.apply { this[rU] = rV }.also { mW[rV] = minOf(mW[rV], mW[rU], r[2]) } else mW.apply { this[rU] = minOf(this[rU], r[2]) } } }.let { mW to p } }.let { (mW, p) -> mW[generateSequence(1) { p[it].takeIf { it != p[it] } }.last()] } }